import os

from flask import Flask, jsonify, redirect, render_template, request, session, url_for
from werkzeug.security import check_password_hash, generate_password_hash

app = Flask(__name__)
app.secret_key = os.environ["SECRET_KEY"]
app.config.update(
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SECURE=True,      # True только на боевом сервере с HTTPS
    SESSION_COOKIE_SAMESITE="Lax",
    PERMANENT_SESSION_LIFETIME=3600,
)

USERS = {
    "anna@example.ru": {
        "id": 7,
        "password_hash": generate_password_hash("correct-horse-battery"),
    }
}


@app.post("/register")
def register():
    data = request.get_json(silent=True) or {}
    email = data.get("email", "")
    password = data.get("password", "")
    if not email or not password:
        return jsonify({"error": {"status": 422, "message": "нужны email и password"}}), 422
    if email in USERS:
        return jsonify({"error": {"status": 409, "message": "такой email уже занят"}}), 409
    user = {"id": len(USERS) + 1, "password_hash": generate_password_hash(password)}
    USERS[email] = user
    return jsonify({"id": user["id"]}), 201


@app.get("/login")
def login_page():
    return render_template("login.html")


@app.post("/login")
def login():
    data = request.get_json(silent=True) or {}
    user = USERS.get(data.get("email", ""))
    # одно сообщение на оба случая: иначе клиент узнаёт, какие email существуют
    if user is None or not check_password_hash(user["password_hash"], data.get("password", "")):
        return jsonify({"error": {"status": 401, "message": "неверный email или пароль"}}), 401
    session.clear()                  # защита от фиксации сессии
    session["user_id"] = user["id"]
    session.permanent = True
    return jsonify({"user_id": user["id"]})


@app.post("/logout")
def logout():
    session.clear()
    # редирект ведёт на GET-маршрут: url_for("login") дал бы 405
    return redirect(url_for("login_page"))


app.run(debug=True)

from functools import wraps

from flask import Flask, jsonify, session

app = Flask(__name__)

TASKS = {1: {"id": 1, "title": "Купить молоко", "owner_id": 7}}


def login_required(view):
    @wraps(view)                    # без wraps endpoint получит имя wrapped
    def wrapped(*args, **kwargs):
        if "user_id" not in session:
            return jsonify({"error": {"status": 401, "message": "нужно войти"}}), 401
        return view(*args, **kwargs)
    return wrapped


def owner_or_403(task):
    if task["owner_id"] != session["user_id"]:
        return jsonify({"error": {"status": 403, "message": "это чужая задача"}}), 403
    return None


@app.get("/api/v1/tasks/<int:task_id>")
@login_required
def task_detail(task_id):
    task = TASKS.get(task_id)
    if task is None:
        return jsonify({"error": {"status": 404, "message": "задача не найдена"}}), 404
    forbidden = owner_or_403(task)
    if forbidden is not None:
        return forbidden
    return jsonify(task)


app.run(debug=True)
